using System;using System.Collections.Generic;using System.Linq;using UnityEngine;public class TaskManager : MonoBehaviour{[Serializable]public class Task{public string id;public string title;public string description;public TaskPriority priority;public bool isCompleted;public DateTime creationTime;public DateTime? completionTime;public float progress;public List<string> tags;public Task(string title,string description = "",TaskPriority priority = TaskPriority.Medium){this.id = Guid.NewGuid().ToString();this.title = title;this.description = description;this.priority = priority;this.isCompleted = false;this.creationTime = DateTime.Now;this.completionTime = null;this.progress = 0f;this.tags = new List<string>();}}public enum TaskPriority{Low,Medium,High,Urgent}[Header("Task Settings")][SerializeField] private bool loadTasksOnStart = true;[SerializeField] private bool autoSaveTasks = true;[SerializeField] private float autoSaveInterval = 60f;[Header("Events")][SerializeField] private bool enableEvents = true;public Action<Task> OnTaskUpdated;public Action<Task> OnTaskCompleted;public Action<Task> OnTaskRemoved;public Action<List<Task>> OnTasksLoaded;private List<Task> _tasks = new List<Task>();private float _timeSinceLastSave = 0f;private void Start(){if(loadTasksOnStart){LoadTasks();}}private void Update(){if(autoSaveTasks){_timeSinceLastSave += Time.deltaTime;if(_timeSinceLastSave >= autoSaveInterval){SaveTasks();_timeSinceLastSave = 0f;}}}public Task CreateTask(string title,string description = "",TaskPriority priority = TaskPriority.Medium){if(string.IsNullOrEmpty(title)){Debug.LogWarning("Cannot create task with empty title");return null;}var task = new Task(title,description,priority);_tasks.Add(task);if(autoSaveTasks){SaveTasks();}if(enableEvents && OnTaskUpdated != null){OnTaskUpdated(task);}return task;}public bool UpdateTask(string taskId,string title = null,string description = null,TaskPriority? priority = null,float progress = -1){var task = _tasks.FirstOrDefault(t => t.id == taskId);if(task == null){Debug.LogWarning($"Cannot update task: Task with ID {taskId} not found");return false;}bool wasUpdated = false;if(title != null){task.title = title;wasUpdated = true;}if(description != null){task.description = description;wasUpdated = true;}if(priority.HasValue){task.priority = priority.Value;wasUpdated = true;}if(progress >= 0){task.progress = Mathf.Clamp01(progress);wasUpdated = true;}if(wasUpdated){if(autoSaveTasks){SaveTasks();}if(enableEvents && OnTaskUpdated != null){OnTaskUpdated(task);}}return wasUpdated;}public bool CompleteTask(string taskId){var task = _tasks.FirstOrDefault(t => t.id == taskId);if(task == null){Debug.LogWarning($"Cannot complete task: Task with ID {taskId} not found");return false;}if(task.isCompleted){return false;}task.isCompleted = true;task.completionTime = DateTime.Now;task.progress = 1f;if(autoSaveTasks){SaveTasks();}if(enableEvents){if(OnTaskUpdated != null){OnTaskUpdated(task);}if(OnTaskCompleted != null){OnTaskCompleted(task);}}return true;}public bool RemoveTask(string taskId){var task = _tasks.FirstOrDefault(t => t.id == taskId);if(task == null){Debug.LogWarning($"Cannot remove task: Task with ID {taskId} not found");return false;}_tasks.Remove(task);if(autoSaveTasks){SaveTasks();}if(enableEvents && OnTaskRemoved != null){OnTaskRemoved(task);}return true;}private void LoadTasks(){try{string json = PlayerPrefs.GetString("Tasks","[]");_tasks = JsonUtility.FromJson<TaskList>(json).tasks;if(enableEvents && OnTasksLoaded != null){OnTasksLoaded(_tasks);}}catch(Exception e){Debug.LogError($"Error loading tasks: {e.Message}");_tasks = new List<Task>();}}private void SaveTasks(){try{var taskList = new TaskList{tasks = _tasks};string json = JsonUtility.ToJson(taskList);PlayerPrefs.SetString("Tasks",json);PlayerPrefs.Save();}catch(Exception e){Debug.LogError($"Error saving tasks: {e.Message}");}}[Serializable]private class TaskList{public List<Task> tasks = new List<Task>();}}
